import unittest

from generated.catalog_client import CatalogClient
from shopapi.listing import fetchAllProducts, getPageCount


class ListingPartialPageRegressionTest(unittest.TestCase):
    def test_page_count_partial_last_page(self):
        self.assertEqual(getPageCount(101, 50), 3)

    def test_page_count_less_than_one_page(self):
        self.assertEqual(getPageCount(1, 50), 1)

    def test_fetch_includes_partial_last_page(self):
        products = fetchAllProducts(CatalogClient(total=101))
        self.assertEqual(len(products), 101)
        self.assertEqual(products[-1]["id"], "P00101")


if __name__ == "__main__":
    unittest.main()

